/**
 * Icons.jsx — Chatly custom SVG icon set
 * All icons accept a `className` prop for size/color control.
 * Color is inherited via `fill="currentColor"` — just set `text-*` on the parent or directly.
 *
 * Usage: <DashboardIcon className="w-5 h-5 text-primary-600" />
 */

const icon = (paths) =>
    ({ className = 'w-5 h-5', ...props }) => (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 512 512"
            className={className}
            aria-hidden="true"
            {...props}
        >
            <g transform="translate(0,512) scale(0.1,-0.1)" fill="currentColor" stroke="none">
                {paths}
            </g>
        </svg>
    );

